CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), risk_tolerance_bps integer NOT NULL CHECK (risk_tolerance_bps BETWEEN 0 AND 10000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS investment_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS plan_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES investment_plans(id), version integer NOT NULL, capital_minor bigint NOT NULL CHECK (capital_minor > 0), daily_loss_limit_minor bigint NOT NULL CHECK (daily_loss_limit_minor > 0), risk_per_trade_minor bigint NOT NULL CHECK (risk_per_trade_minor > 0), max_trades integer NOT NULL CHECK (max_trades >= 0), effective_at timestamptz NOT NULL, UNIQUE(plan_id, version));
CREATE TABLE IF NOT EXISTS accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), environment text NOT NULL CHECK (environment IN ('simulation','paper','live')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trades (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts(id), plan_version_id uuid REFERENCES plan_versions(id), net_pnl_minor bigint NOT NULL, fees_minor bigint NOT NULL DEFAULT 0 CHECK (fees_minor >= 0), mode text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts(id), idempotency_key text NOT NULL, state text NOT NULL, requested_risk_minor bigint NOT NULL CHECK (requested_risk_minor >= 0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id, idempotency_key));
CREATE TABLE IF NOT EXISTS positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts(id), instrument text NOT NULL, quantity numeric(30,10) NOT NULL, cost_minor bigint NOT NULL, state text NOT NULL);
CREATE TABLE IF NOT EXISTS strategies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS strategy_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), strategy_id uuid NOT NULL REFERENCES strategies(id), version_hash text NOT NULL UNIQUE, approval_status text NOT NULL DEFAULT 'sandbox');
CREATE TABLE IF NOT EXISTS profit_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), batch_id uuid NOT NULL, realized_profit_minor bigint NOT NULL CHECK (realized_profit_minor >= 0), short_minor bigint NOT NULL, long_minor bigint NOT NULL, withdraw_minor bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, batch_id));
CREATE TABLE IF NOT EXISTS portfolio_holdings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), instrument text NOT NULL, quantity numeric(30,10) NOT NULL, cost_basis_minor bigint NOT NULL);
CREATE TABLE IF NOT EXISTS bot_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts(id), state text NOT NULL, emergency_stop boolean NOT NULL DEFAULT false, started_at timestamptz, stopped_at timestamptz);
CREATE TABLE IF NOT EXISTS ai_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), agent_type text NOT NULL, strategy_version_id uuid REFERENCES strategy_versions(id), proposal jsonb NOT NULL, risk_check jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), action text NOT NULL, entity text NOT NULL, entity_id uuid, request_id text NOT NULL, previous_state jsonb, new_state jsonb, source text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
